        ("کیڑوں کا حملہ دیسی چنے پر زیادہ ہوتا ہے یا کابلی پر؟", "کابلی چنے کا چھلکا باریک اور میٹھا ہوتا ہے، اس لیے اس پر دیسی چنے کے مقابلے میں سنڈی اور دیگر کیڑوں کا حملہ زیادہ ہوتا ہے۔", "اقسام: دیسی بمقابلہ کابلی"),
        ("چنے میں پروٹین کی مقدار کتنی ہوتی ہے؟", "چنا انسانی صحت کے لیے پروٹین کا بہترین ذریعہ ہے، اس میں عام طور پر 20 سے 24 فیصد تک پروٹین پائی جاتی ہے۔", "بنیادی معلومات"),
        ("کیا چنا ایسی زمین میں اگ سکتا ہے جہاں پانی کھڑا ہوتا ہو؟", "بالکل نہیں؛ چنا سیم زدہ یا پانی کھڑی رہنے والی زمین میں فوری طور پر مر جاتا ہے۔ اس کے لیے اچھے نکاس والی زمین ضروری ہے۔", "بنیادی معلومات"),
        ("پاکستان میں چنے کی چند منظور شدہ جدید اقسام کے نام بتائیں۔", "مشہور اقسام میں 'تھل-2006'، 'پنجاب-2008'، 'بٹل-2016'، اور 'نور-2013' (کابلی) شامل ہیں۔", "اقسام: دیسی بمقابلہ کابلی"),
        ("چنے کے پودے کا قد کتنا ہوتا ہے؟", "قسم اور زمین کی زرخیزی کے لحاظ سے پودا 1 سے 2 فٹ تک اونچا ہو سکتا ہے۔", "بنیادی معلومات"),
        ("چنے کے پتے چکھنے میں کھٹے کیوں محسوس ہوتے ہیں؟", "چنے کے پتوں پر موجود غدود سے قدرتی طور پر 'ملک ایسڈ' اور 'آگزالک ایسڈ' خارج ہوتا ہے، جو پودے کو کیڑوں سے بچاتا ہے اور اسے کھٹا ذائقہ دیتا ہے۔", "بنیادی معلومات"),
        ("کیا چنا زمین کی زرخیزی بڑھانے میں مدد دیتا ہے؟", "جی ہاں، چنا اپنی جڑوں میں موجود خاص بیکٹیریا کی مدد سے ہوا سے نائٹروجن جذب کر کے زمین میں جمع کرتا ہے، جس سے زمین کی طاقت بڑھ جاتی ہے۔", "بنیادی معلومات"),
        ("چنے کے بیج کو ذخیرہ کرنے کے لیے نمی کی کتنی مقدار ہونی چاہیے؟", "ذخیرہ کرتے وقت بیج میں نمی 10 فیصد سے زیادہ نہیں ہونی چاہیے، ورنہ اسے 'دھورا' (گھن) لگنے کا خطرہ ہوتا ہے۔", "بنیادی معلومات"),
        ("بوائی سے پہلے بیج کا اگاؤ (Germination) چیک کرنا کیوں ضروری ہے؟", "تاکہ یہ یقینی بنایا جا سکے کہ بیج صحت مند ہے اور کھیت میں پودوں کی تعداد پوری رہے گی۔", "بنیادی معلومات"),
        ("کیا کابلی چنے کی فی ایکڑ پیداوار دیسی سے زیادہ ہوتی ہے؟", "عام طور پر دیسی چنے کی پیداوار زیادہ مستحکم ہوتی ہے، جبکہ کابلی چنا حساس ہونے کی وجہ سے زیادہ دیکھ بھال مانگتا ہے۔", "اقسام: دیسی بمقابلہ کابلی"),
    
        # --- زمین کی تیاری اور بوائی (31 سے 60) ---
        ("بارانی علاقوں میں چنے کے لیے زمین کی تیاری کا صحیح طریقہ کیا ہے؟", "بارانی علاقوں میں کوشش کرنی چاہیے کہ بارش کا زیادہ سے زیادہ پانی زمین میں جذب ہو، اس کے لیے گہرا ہل چلایا جاتا ہے لیکن بوائی کے وقت وتر بچانے کے لیے کم ہل چلانا چاہیے۔", "زمین کی تیاری"),
        ("تھل کے ریتلی ٹیلوں پر ہل چلانے میں کیا احتیاط کرنی چاہیے؟", "تھل میں زیادہ ہل نہیں چلانا چاہیے، کیونکہ ریتلی مٹی اڑنے کا خطرہ ہوتا ہے اور زمین کی نمی بھی ختم ہو جاتی ہے۔", "زمین کی تیاری"),
        ("چنے کی بوائی کا 'پور' والا طریقہ کیا ہے؟", "یہ پرانا طریقہ ہے جس میں ہل کے پیچھے نالی لگا کر بیج کو گہرائی میں ڈالا جاتا ہے جہاں وتر (نمی) موجود ہو۔", "بوائی کا طریقہ"),
        ("بارانی علاقوں میں بیج کتنی گہرائی میں بونا چاہیے؟", "نمی کا فائدہ اٹھانے کے لیے بیج کو 4 سے 6 انچ گہرا بونا چاہیے تاکہ پودا سوکھنے سے بچ سکے۔", "زمین کی تیاری"),
        ("اگر بیج اوپر کی خشک مٹی میں بوج دیا جائے تو کیا ہوگا؟", "بیج یا تو اگے گا نہیں، اور اگر اگ آیا تو تھوڑی سی دھوپ لگنے پر پودا سوکھ کر مر جائے گا۔", "زمین کی تیاری"),
        ("آبپاش علاقوں میں بیج کی گہرائی کتنی ہونی چاہیے؟", "جہاں پانی کی سہولت ہو، وہاں 2 سے 3 انچ گہرائی کافی ہوتی ہے۔", "زمین کی تیاری"),
        ("پنجاب کے بارانی علاقوں میں بوائی کا موزوں ترین وقت کیا ہے؟", "یکم اکتوبر سے 15 اکتوبر تک کا وقت بہترین ہے تاکہ زمین کی نمی کا بھرپور فائدہ اٹھایا جا سکے۔", "بوائی کا وقت"),
        ("آبپاش علاقوں میں چنا کب بونا چاہیے؟", "آبپاش علاقوں میں 15 اکتوبر سے 15 نومبر تک بوائی کی جا سکتی ہے۔", "بوائی کا وقت"),
        ("اگر چنا ستمبر میں بوج دیا جائے تو کیا نقصان ہو سکتا ہے؟", "بہت جلد بوائی سے پودا ضرورت سے زیادہ بڑھ جاتا ہے جس پر کیڑوں اور بیماریوں کا حملہ بڑھ جاتا ہے۔", "بوائی کا وقت"),
        ("چنے کی بوائی میں زیادہ تاخیر (دسمبر) کا کیا نتیجہ نکلتا ہے؟", "دیر سے بونی گئی فصل کا قد چھوٹا رہ جاتا ہے اور وہ بھرپور پیداوار نہیں دے پاتی۔", "بوائی کا وقت"),
        ("دیسی چنے کے لیے فی ایکڑ کتنا بیج درکار ہوتا ہے؟", "بارانی علاقوں کے لیے 25 سے 30 کلوگرام، جبکہ آبپاش علاقوں کے لیے 20 سے 25 کلوگرام کافی ہے۔", "بیج کی شرح"),
        ("کابلی چنے کا کتنا بیج فی ایکڑ ڈالنا چاہیے؟", "کابلی بیج بڑا اور وزنی ہوتا ہے، اس لیے 35 سے 45 کلوگرام بیج فی ایکڑ استعمال کرنا چاہیے۔", "بیج کی شرح"),
        ("قطاروں کے درمیان کتنا فاصلہ رکھنا ضروری ہے؟", "قطاروں کا درمیانی فاصلہ ایک سے ڈیڑھ فٹ (12-18 انچ) ہونا چاہیے تاکہ ہوا کی آمد و رفت بہتر ہو۔", "بوائی کا طریقہ"),
        ("گھنی فصل بونے کا سب سے بڑا نقصان کیا ہے؟", "اگر فصل بہت گھنی ہو تو اس میں 'جھلساؤ' (Blight) کی بیماری تیزی سے پھیلتی ہے اور سپرے کرنا بھی مشکل ہوتا ہے۔", "بوائی کا طریقہ"),
        ("زمین کی 'وتر' حالت سے کیا مراد ہے؟", "وتر وہ حالت ہے جب مٹی میں اتنی نمی ہو کہ بیج آسانی سے اگ سکے؛ ہاتھ میں مٹی دبانے سے گولا تو بنے لیکن وہ گولا بکھر بھی سکے۔", "زمین کی تیاری"),
        ("کیا بیج کا چھٹہ دینا چنے کے لیے اچھا ہے؟", "نہیں، چھٹہ دینے سے بیج یکساں گہرائی پر نہیں جاتا، جس کی وجہ سے آدھا اگتا ہے اور آدھا پرندے کھا جاتے ہیں۔", "بوائی کا طریقہ"),
        ("دھان (چاول) کی کٹائی کے بعد چنے کے لیے زمین کیسے تیار کریں؟", "دھان کے بعد زمین سخت ہو جاتی ہے، اس لیے 'چیزل پلاؤ' (گہرا ہل) چلا کر سخت تہہ توڑنا ضروری ہے تاکہ چنے کی جڑیں نیچے جا سکیں۔", "زمین کی تیاری"),
        ("بارانی علاقوں میں زمین کو ہموار (لیول) کیوں نہیں کیا جاتا؟", "تھوڑی بہت ناہمواری بارش کا پانی روکنے میں مدد دیتی ہے، ورنہ سارا پانی بہہ کر ضائع ہو جائے گا۔", "زمین کی تیاری"),
        ("بیج کو پھپھوندی کش زہر لگانا کیوں لازمی ہے؟", "بیج کو زہر لگانے سے وہ زمین میں موجود بیماریوں اور شروع میں مرجھانے (Wilt) سے محفوظ رہتا ہے۔", "بیج کا علاج"),
        ("کیا چنے کو بغیر ہل چلائے (زیرو ٹیلیج) بویا جا سکتا ہے؟", "جی ہاں، نمی بچانے اور خرچہ کم کرنے کے لیے یہ طریقہ کامیاب ثابت ہو رہا ہے۔", "بوائی کا طریقہ"),
    
        # --- پنجاب کا مرکز (تھل ریجن) (61 سے 100) ---
        ("پاکستان میں چنے کی کاشت کا سب سے بڑا علاقہ کون سا ہے؟", "پنجاب کا 'تھل ریجن' (بھکر، لیہ، خوشاب، میانوالی) چنے کی کاشت کا سب سے بڑا گڑھ ہے۔", "صوبائی مرکز: پنجاب"),
        ("تھل کی زمین چنے کے لیے کیوں بہترین سمجھی جاتی ہے؟", "تھل کی ریتلی زمین اور وہاں کی آب و ہوا چنے کی فصل کے لیے قدرتی طور پر بہت سازگار ہے۔", "صوبائی مرکز: پنجاب"),
        ("تھل کے کسانوں کو ریتلی آندھیوں سے کیا خطرہ ہوتا ہے؟", "اکتوبر نومبر میں چلنے والی ہوائیں چھوٹے پودوں کو ریت میں دبا دیتی ہیں، جس سے اگاؤ متاثر ہوتا ہے۔", "صوبائی مرکز: پنجاب"),
        ("تھل کا چنا زیادہ تر بارش پر پلتا ہے یا نہر پر؟", "تھل کی فصل تقریباً 100 فیصد بارانی ہے، یعنی اس کا سارا دارومدار بارش پر ہوتا ہے۔", "صوبائی مرکز: پنجاب"),
        ("اگر جنوری فروری میں تھل میں بارش نہ ہو تو کیا ہوتا ہے؟", "بارش نہ ہونے کی صورت میں فصل سوکھنے لگتی ہے اور پیداوار میں بہت زیادہ کمی آ جاتی ہے۔", "صوبائی مرکز: پنجاب"),
        ("پنجاب میں چنے کی فصل پر 'جھلساؤ' (Ascochyta Blight) کب حملہ کرتا ہے؟", "جب فروری مارچ میں مسلسل بارشیں ہوں اور بادل چھائے رہیں، تو یہ بیماری پوری فصل کو چند دنوں میں تباہ کر سکتی ہے۔", "بیماریوں کا انتظام"),
        ("تھل کے کسان کھاد کا استعمال کم کیوں کرتے ہیں؟", "چونکہ یہ بارش پر منحصر فصل ہے، اس لیے کسان زیادہ خرچہ کرنے سے ڈرتے ہیں کہ کہیں سوکھا پڑنے سے سرمایہ ضائع نہ ہو جائے۔", "صوبائی مرکز: پنجاب"),
        ("کیا تھل میں چنے کی کٹائی مشینوں سے ہوتی ہے؟", "زیادہ تر کٹائی ہاتھوں سے کی جاتی ہے، کیونکہ ریتلے ٹیلوں پر بڑی مشینیں چلانا مشکل ہوتا ہے۔", "صوبائی مرکز: پنجاب"),
        ("پنجاب کے کسان 'اوکھیڑا' (Wilt) سے کیسے بچتے ہیں؟", "اس کا بہترین حل ایسی اقسام کی کاشت ہے جو بیماری کے خلاف قوتِ مدافعت رکھتی ہوں۔", "بیماریوں کا انتظام"),
        ("تھل کے کسانوں کی معیشت میں چنے کا کیا مقام ہے؟", "چنا تھل کے کسانوں کی واحد بڑی نقد آور فصل ہے، جس پر ان کے پورے سال کے اخراجات کا دارومدار ہوتا ہے۔", "صوبائی مرکز: پنجاب"),
        ("بھکر میں واقع 'ایریڈ زون ریسرچ انسٹی ٹیوٹ' (AZRI) کا کیا کردار ہے؟", "یہ ادارہ خاص طور پر تھل کے حالات کے مطابق چنے کی نئی اقسام اور کاشت کے طریقے ایجاد کرتا ہے۔", "صوبائی مرکز: پنجاب"),
        ("پنجاب میں 'چھولیا' کسے کہتے ہیں؟", "چنے کی کچی اور ہری پھلیوں کو چھولیا کہتے ہیں، جسے کسان پکا کر یا بھون کر کھانے کے لیے شہروں میں بیچتے ہیں۔", "صوبائی مرکز: پنجاب"),
        ("چھولیا بیچنے کا کسان کو کیا فائدہ ہوتا ہے؟", "اس سے کسان کو نقد رقم جلدی مل جاتی ہے اور فصل کو سنڈی سے بچانے کا سپرے بھی نہیں کرنا پڑتا۔", "صوبائی مرکز: پنجاب"),
