    ("کھلے کھیت میں ٹماٹر کی آبپاشی کیسے کرنی چاہیے؟", "ٹماٹر کو ہمیشہ کھالیوں (Furrows) کے ذریعے پانی دینا چاہیے۔ پانی کبھی بھی پودے کے تنے یا پتوں کو نہیں چھونا چاہیے ورنہ جڑیں گل سکتی ہیں۔", "زرعی مہارت"),
    ("ٹماٹر کے لیے ڈرپ اریگیشن کیوں بہترین ہے؟", "یہ پانی کی 50 فیصد تک بچت کرتی ہے، جڑی بوٹیاں کم اگتی ہیں اور پتوں کو خشک رکھ کر پھپھوندی کی بیماریوں کو روکتی ہے۔", "زرعی مہارت"),
    ("بلاسم اینڈ روٹ (BER) کیا ہے اور یہ کیوں ہوتا ہے؟", "یہ ٹماٹر کی ایک خرابی ہے جس میں پھل کا نچلا حصہ کالا اور دھنسا ہوا نظر آتا ہے۔ یہ کیلشیم کی کمی اور پانی کے غیر متوازن استعمال کی وجہ سے ہوتا ہے۔", "زرعی مہارت"),
    ("ٹماٹر میں 'سٹیکنگ' (Staking) سے کیا مراد ہے؟", "سٹیکنگ کا مطلب پودے کو لکڑی یا بانس کے سہارے کے ساتھ باندھنا ہے تاکہ پھل زمین سے اونچا رہے اور سڑنے سے بچ جائے۔", "زرعی مہارت"),
    ("ٹنل فارمنگ میں غیر محدود (Indeterminate) اقسام کی تراش خراش کیوں ضروری ہے؟", "فالتو شاخیں (Suckers) کاٹنے سے پودے کی ساری توانائی پھل بنانے پر صرف ہوتی ہے اور ہوا کا گزر بھی بہتر رہتا ہے۔", "زرعی مہارت"),

    # --- کیڑوں کا انتظام (27 سے 32) ---
    ("ٹماٹر کا پھل خور سنڈی (Fruit Borer) کیسے نقصان پہنچاتی ہے؟", "یہ سنڈی سبز اور پکے ہوئے پھل میں سوراخ کر کے اسے اندر سے کھاتی ہے، جس سے پھل مارکیٹ کے قابل نہیں رہتا۔", "کیڑوں کا انتظام"),
    ("سفید مکھی (Whitefly) ٹماٹر کے لیے کیوں خطرناک ہے؟", "یہ نہ صرف پودے کا رس چوستی ہے بلکہ 'ٹماٹر کے پتے مروڑ وائرس' (Leaf Curl Virus) کو پھیلانے کا سب سے بڑا ذریعہ ہے۔", "کیڑوں کا انتظام"),
    ("سفید مکھی کو کنٹرول کرنے کا بہترین طریقہ کیا ہے؟", "ایمیڈا کلوپرڈ یا ڈائی فینتھیوران کا سپرے کریں اور ٹنل میں پیلے رنگ کے 'اسٹکی ٹریپس' (Sticky Traps) لگائیں۔", "کیڑوں کا انتظام"),
    ("تھرپس (Thrips) ٹماٹر کو کیا نقصان پہنچاتے ہیں؟", "تھرپس پتوں اور پھولوں کو رگڑ کر رس چوستے ہیں جس سے پتے اوپر کی طرف مڑ جاتے ہیں اور ان پر چاندی جیسی چمک آ جاتی ہے۔", "کیڑوں کا انتظام"),
    ("ٹماٹر کے سست تیلے (Aphids) کا علاج کیا ہے؟", "تیلا پودے کے نئے شگوفوں پر حملہ کرتا ہے۔ اس کے لیے سسٹمک ادویات (جیسے امیڈا کلوپرڈ) کا سپرے کریں۔", "کیڑوں کا انتظام"),
    ("لیف مائنر (Leaf Miner) کی پہچان کیا ہے؟", "لیف مائنر پتوں کے اندر سفید رنگ کی ٹیڑھی میڑھی لکیریں (سرنگیں) بناتی ہے۔ اس کے لیے ایبامیکٹن کا سپرے مفید ہے۔", "کیڑوں کا انتظام"),

